questionvariables.text:
/* Design: classify pattern. Kinds 1 upT, 2 upM, 3 downT, 4 downM, 5 line. Pools checked for bend and positivity. Source: original. */
upl: [[[2,0,1],0,3],[[1,0,0,1],0,2],[[5,-2,1],1,4],[[3,0,0,2],1,3],[[4,1,2],0,2],[[6,-4,1],2,5],[[1,0,3],0,2],[[2,0,0,1],0,3]];
dnl: [[[10,0,-1],0,3],[[8,2,-1],0,3],[[20,0,0,-1],0,2],[[12,4,-1],1,5],[[9,0,-1],0,2],[[30,0,0,-2],1,2],[[6,1,-1],0,2],[[15,2,-1],1,4]];
lnl: [[[1,3],0,4],[[5,-1],0,3],[[2,4],1,5],[[7,-2],0,3],[[3,2],1,4],[[10,-3],0,2]];
P: [[3,1,5,2,4],[2,5,1,4,3],[5,3,2,1,4],[4,2,3,5,1],[1,4,2,5,3],[2,3,5,4,1],[5,1,4,3,2],[3,4,1,2,5],[4,5,3,1,2],[1,3,4,2,5]];
ix: 1+rand(10);
pm: P[ix];
mk(cl) := sum(cl[j]*x^(j-1), j, 1, length(cl));
itm: [upl[mod(ix,8)+1], upl[mod(ix+3,8)+1], dnl[mod(ix,8)+1], dnl[mod(ix+5,8)+1], lnl[mod(ix,6)+1]];
rul: makelist(if kd = 5 then (if is(mod(ix,2)=0) then "trapezoidal" else "mid-ordinate") else ["trapezoidal", "mid-ordinate", "trapezoidal", "mid-ordinate"][kd], kd, 1, 5);
corr: ["o", "u", "u", "o", "e"];
/* row r shows kind pm[r]; rw[kd] is the row of kind kd */
IP: [[2,4,1,5,3],[3,1,5,4,2],[4,3,2,5,1],[5,2,3,1,4],[1,3,5,2,4],[5,1,2,4,3],[2,5,4,3,1],[3,4,1,2,5],[4,5,3,1,2],[1,4,2,3,5]];
rw: IP[ix];
fr: makelist(mk(itm[pm[r]][1]), r, 1, 5);
lr: makelist(itm[pm[r]][2], r, 1, 5);
hr: makelist(itm[pm[r]][3], r, 1, 5);
rr: makelist(rul[pm[r]], r, 1, 5);
kc: makelist(sconcat(corr[pm[r]], r), r, 1, 5);
mko(r) := [[sconcat("o", r), is(corr[pm[r]] = "o"), "an overestimate"], [sconcat("u", r), is(corr[pm[r]] = "u"), "an underestimate"], [sconcat("e", r), is(corr[pm[r]] = "e"), "the exact area"]];
o1: mko(1); o2: mko(2); o3: mko(3); o4: mko(4); o5: mko(5);
/* test vectors: both T rows reversed; both M rows reversed; line row "over"; upT row "exact" */
tT: makelist(if is(r = rw[1]) then sconcat("u", r) else if is(r = rw[3]) then sconcat("o", r) else kc[r], r, 1, 5);
tM: makelist(if is(r = rw[2]) then sconcat("o", r) else if is(r = rw[4]) then sconcat("u", r) else kc[r], r, 1, 5);
tL: makelist(if is(r = rw[5]) then sconcat("o", r) else kc[r], r, 1, 5);
tG: makelist(if is(r = rw[1]) then sconcat("e", r) else kc[r], r, 1, 5);

feedbackvariables.text:
A: [ans1, ans2, ans3, ans4, ans5];
mk1: makelist(if is(A[r] = kc[r]) then 1 else 0, r, 1, 5);
ncorrect: apply("+", mk1);
swapT: is(A[rw[1]] = sconcat("u", rw[1])) and is(A[rw[3]] = sconcat("o", rw[3]));
swapM: is(A[rw[2]] = sconcat("o", rw[2])) and is(A[rw[4]] = sconcat("u", rw[4]));
linewrong: not is(A[rw[5]] = sconcat("e", rw[5]));
